html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}

{% if letter_head and not no_letterhead %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
{% if print_heading_template %}
{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break committee-page">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<style>
		.letter-head {
			padding-top: 12px !important;
			padding-bottom: 12px !important;
		}
		.committee-page {
			font-family: Inter, sans-serif;
			color: #171717;
		}

		.print-format-body {
			padding: 30px 12px 12px 12px !important;
		}

		.title {
			color: #7c7c7c !important;
		}
		.text-muted {
			color: #7c7c7c !important;
		}
		.text-dark {
			color: #171717 !important;
		}
		.small-text {
			font-size: 11px;
			color: #666;
		}

		.text-left {
			text-align: left;
		}
		.text-center {
			text-align: center;
		}
		.text-right {
			text-align: right;
		}
		.text-bold {
			font-weight: 700;
		}

		.mt-15 {
			margin-top: 15px;
		}
		.mt-16 {
			margin-top: 16px;
		}
		.mt-40 {
			margin-top: 40px;
		}
		.mw-400 {
			max-width: 400px;
		}

		.items-table,
		.tax-table {
			width: 100%;
			border-collapse: separate;
			border-spacing: 0;
			border-radius: 10px;
			overflow: hidden;
		}

		.items-table td,
		.tax-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px;
		}

		.items-table thead td,
		.tax-table thead td {
			color: #7c7c7c !important;
		}
		.items-table thead tr:first-of-type td,
		.tax-table thead tr:first-of-type td {
			border-bottom: none;
		}

		.items-table thead tr:first-child td:first-child,
		.tax-table thead tr:first-child td:first-child {
			border-top-left-radius: 10px;
			border-bottom-left-radius: 10px;
		}
		.items-table thead tr:first-child td:last-child,
		.tax-table thead tr:first-child td:last-child {
			border-top-right-radius: 10px;
			border-bottom-right-radius: 10px;
		}

		.in-words {
			color: #171717 !important;
			max-width: 400px;
			word-wrap: break-word;
			line-height: 1.5;
			font-size: 12px;
		}

		.row-divider {
			border-bottom: 1px solid #e9e9e9;
		}

		.highlight-bg {
			background: #f8f8f8;
		}

		.info-card {
			margin-top: 40px;
			color: #7c7c7c;
		}

		.info-text {
			margin-bottom: 12px;
		}

		.print-format {
			color: #171717;
			font-size: 14px;
			font-style: normal;
			font-weight: 420;
			line-height: 21px;
			padding: 0px !important;
			margin-left: 0mm !important;
			margin-right: 0mm !important;
		}

		.letter-head-footer {
			margin-top: 0px !important;
		}

		.print-format-body td {
			padding: 8px 8px !important;
		}

		.tax-table td,
		.items-table td {
			height: auto !important;
		}

		.tax-table thead td,
		.items-table thead td {
			height: 32px;
		}

		.item-img td {
			border: none !important;
			padding: 0px !important;
		}
	</style>

	<div class="print-format-body">
		<table class="info-table col-xs-12" style="width: 100%; margin-left: 12px">
			<tr>
				<td class="col-xs-6" style="padding: 0 !important">
					<div class="title col-xs-5 p-0">
						<div class="info-text">{{ _("Request for Quotation:") }}</div>
						<div class="info-text">{{ _("Note Type:") }}</div>
					</div>
					<div class="col-xs-7">
						<div class="info-text">{{ doc.quotation }}</div>
						<div class="info-text">
						    {{ frappe.utils.format_date(doc.posting_date)  }}
						</div>

					</div>
				</td>

				<td class="col-xs-6" style="padding: 0 !important">
					<div class="title col-xs-5 p-0">
						<div class="info-text">{{ _("Note Type:") }}</div>
					</div>
					<div class="col-xs-7">
						<div class="info-text">{{ doc.note_type }}</div>
					</div>
					<div class="title col-xs-5 p-0">
						<div class="info-text">{{ _("Committe:") }}</div>
					</div>
					<div class="col-xs-7">
						<div class="info-text">{{ doc.committee }}</div>
					</div>
				</td>
			</tr>
		</table>
	</div>
<div style="padding-left: 20px; padding-right: 20px">{{ doc.generated_content | safe }}</div>
</div>
{% endfor %}
